from pathlib import Path
import re
p=Path('pantry.html')
s=p.read_text(encoding='utf-8-sig')
# Robot command UI palette
for a,b in {'#1a1410':'#07111f','#241c15':'#0d1b2d','#31261a':'#14263d','#3e3122':'#1d3652','#4a3b28':'#2b4968','#e8a838':'#35d8ff','#f7c463':'#8cecff','#c4442e':'#d84cff','#e05a3f':'#ff72e8','#6fbf8f':'#5ff0c0','#f0e4d0':'#e8f6ff','#9b8a70':'#7894af','#f0c14b':'#66e7ff','#7a5215':'#11627d','#6b1e12':'#68126d','#15100c':'#050b14'}.items(): s=s.replace(a,b)
css='''\n/* ROBOTS VS ALIENS COMMAND UI */\nbody{background:radial-gradient(circle at 40% 10%,#122943,#07111f 55%,#030811)}\n#shop{background:linear-gradient(180deg,rgba(7,18,32,.99),rgba(3,10,20,.99));border-left-color:#2b617e;box-shadow:-12px 0 35px rgba(0,0,0,.35),inset 1px 0 rgba(53,216,255,.12)}\n#shop:before{content:"ROBOT DEPLOYMENT";display:block;color:#5ff0c0;font-size:9px;letter-spacing:.18em;font-weight:900;padding:0 2px 8px;border-bottom:1px solid #2b4968;margin-bottom:8px}\n#hud{background:linear-gradient(rgba(4,13,25,.97),rgba(4,13,25,0))}\n.pill{background:linear-gradient(160deg,rgba(12,29,47,.96),rgba(4,10,20,.94));border-color:#2b4968}.pill.cash{color:#66e7ff}.pill.life{color:#ff72e8}.pill.wave{color:#5ff0c0}\n.tcard.sel,.stab.sel{border-color:#35d8ff;background:#142b43}.btn{border-left-color:#35d8ff}.card.sel{border-left-color:#35d8ff}.hbtn.go{border-color:#5ff0c0;color:#5ff0c0}.hbtn.go.fast{background:#5ff0c0;color:#061b16}\n.logo{color:#35d8ff;text-shadow:0 3px 0 #11627d}.logo span{color:#d84cff;text-shadow:0 3px 0 #68126d}\n.robot-scanline{position:absolute;inset:0;pointer-events:none;z-index:5;background:repeating-linear-gradient(0deg,rgba(70,220,255,.018) 0,rgba(70,220,255,.018) 1px,transparent 1px,transparent 4px);mix-blend-mode:screen}\n'''
if 'ROBOTS VS ALIENS COMMAND UI' not in s:s=s.replace('</style>',css+'</style>',1)
s=s.replace('The invasion found Earth. Hold the line.','Earth is under attack. Deploy the robots. Hold the line.')
# Distinct alien silhouettes. Prefer replacing the existing renderer, otherwise inject an override.
alien=r'''function drawBugArt(c,kind,t,r,wob){var B=BUGS[kind]||{},col=B.col||"#62edff",i=Math.max(0,Object.keys(BUGS||{}).indexOf(kind))%8,p=.7+.3*Math.sin(t*4+(wob||0));var M="#142b43",C="#62edff",P="#ef63ff";c.save();c.translate(0,Math.sin(t*3+(wob||0))*.6);c.scale(r/12,r/12);function e(x,y,z){c.fillStyle="#020812";c.beginPath();c.arc(x,y,z,0,6.283);c.fill();c.fillStyle=C;c.globalAlpha=p;c.beginPath();c.arc(x,y,z*.45,0,6.283);c.fill();c.globalAlpha=1}function l(a,b,d,e,w){c.strokeStyle=M;c.lineWidth=w;c.lineCap="round";c.beginPath();c.moveTo(a,b);c.lineTo(d,e);c.stroke();c.strokeStyle=col;c.lineWidth=Math.max(1,w*.3);c.stroke()}c.fillStyle=M;c.strokeStyle=col;c.lineWidth=1.6;if(i===0){c.beginPath();c.roundRect(-8,-7,16,14,4);c.fill();c.stroke();e(-3,-1,1.7);e(3,-1,1.7);l(-5,5,-10,9,2);l(5,5,10,9,2)}else if(i===1){c.beginPath();c.ellipse(0,1,10,5,0,0,6.283);c.fill();c.stroke();c.fillStyle="rgba(98,237,255,.18)";c.beginPath();c.ellipse(-9,-5,7,3,0,0,6.283);c.ellipse(9,-5,7,3,0,0,6.283);c.fill();e(0,0,2)}else if(i===2){c.beginPath();c.moveTo(-10,0);c.lineTo(-4,-7);c.lineTo(5,-5);c.lineTo(10,0);c.lineTo(5,5);c.lineTo(-4,7);c.closePath();c.fill();c.stroke();e(4,-1,1.8);l(-6,3,-12,8,1.6);l(6,3,12,8,1.6)}else if(i===3){c.beginPath();c.ellipse(0,1,9,7,0,0,6.283);c.fill();c.stroke();c.strokeStyle=C;c.beginPath();c.moveTo(0,-6);c.lineTo(0,7);c.stroke();e(-3,-1,1.3);e(3,-1,1.3);l(-6,4,-11,9,1.5);l(6,4,11,9,1.5)}else if(i===4){c.beginPath();c.moveTo(-11,5);c.lineTo(-6,-8);c.lineTo(0,-11);c.lineTo(6,-8);c.lineTo(11,5);c.lineTo(0,9);c.closePath();c.fill();c.stroke();e(0,-2,2.2);c.strokeStyle=P;c.beginPath();c.arc(0,0,7,0,6.283);c.stroke()}else if(i===5){c.beginPath();c.ellipse(0,0,7,10,0,0,6.283);c.fill();c.stroke();c.strokeStyle=col;c.lineWidth=2;for(var q=-5;q<=5;q+=5){c.beginPath();c.moveTo(q,-4);c.lineTo(q+2,5);c.stroke()}e(0,-3,1.7);l(-5,5,-9,10,1.5);l(5,5,9,10,1.5)}else if(i===6){c.beginPath();c.roundRect(-10,-7,20,14,5);c.fill();c.stroke();e(-3,-1,1.4);e(3,-1,1.4);c.strokeStyle=C;c.beginPath();c.arc(0,0,11,0,6.283);c.stroke()}else{c.beginPath();c.ellipse(0,0,20,12,0,0,6.283);c.fill();c.stroke();c.strokeStyle=P;c.lineWidth=2;c.beginPath();c.arc(0,0,15+Math.sin(t*3)*1.5,0,6.283);c.stroke();for(var z=0;z<6;z++){var a=z*Math.PI/3;l(Math.cos(a)*10,Math.sin(a)*7,Math.cos(a)*25,Math.sin(a)*17,1.6)}e(0,0,3)}c.shadowBlur=0;c.restore();}
'''
if 'function drawBugArt' in s:
    start=s.index('function drawBugArt'); marker=s.find('function drawTowerArt',start)
    if marker>start:s=s[:start]+alien+'\n'+s[marker:]
    else:s=s.replace('</script>',alien+'</script>',1)
else:s=s.replace('</script>',alien+'</script>',1)
if 'UI + ENEMY VISUAL REWORK' not in s:
    m=re.search(r'\{v:["\']2\.0(?:\.0)?["\'][^\n]*items:\s*\[',s)
    entry='/* 2.0 CHANGELOG: UI + ENEMY VISUAL REWORK - Robots vs Aliens command UI, cyan robot accents, magenta alien energy, metallic panels, right-side Robot Deployment shop, and distinct alien silhouettes replacing generic bug visuals while preserving enemy ids and stats. */\n'
    if m:s=s[:m.start()]+entry+s[m.start():]
    else:s=s.replace('</body>',entry+'</body>',1)
p.write_text(s,encoding='utf-8')
